// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "./interface/SecondSwap_IMarketplaceSetting.sol";
import "./interface/SecondSwap_IWhitelist.sol";
import "./interface/SecondSwap_IVestingManager.sol";
import "./SecondSwap_WhitelistDeployer.sol";
// TODO Remove
import "hardhat/console.sol";


contract SecondSwap_Marketplace is Initializable {
    enum Status { LIST, SOLDOUT, DELIST }
    enum ListingType { PARTIAL, SINGLE }
    enum DiscountType { NO, LINEAR, FIX }
    struct Listing {
        address seller;
        uint256 total;
        uint256 balance;
        uint256 pricePerUnit;
        ListingType listingType;
        DiscountType discountType;
        uint256 discountPct;
        uint256 listTime;
        address whitelist;
        uint256 minPurchaseAmt;
        Status status;
        address currency;
    }
    address public marketplaceSetting;
    mapping(address => mapping(uint256 => Listing)) public listings;
    mapping(address => uint256) public nextListingId;
    mapping(address => bool) public isTokenSupport;

    uint256 public constant BASE = 10000;

    event Listed(address indexed vestingPlan, uint256 indexed listingId);
    event Delisted(address indexed vestingPlan, uint256 indexed listingId,uint256 penaltyFee,address seller);
    event Purchased(address indexed vestingPlan,uint256 indexed listingId,address buyer, uint256 amount ,address referral,uint256 buyerFee,uint256 sellerFee,uint256 referralReward);
    event WhitelistCreated(address indexed vestingPlan, uint256 indexed listingId,address whitelistAddress,address seller,uint256 maxWhitelist);

    // TODO uncomment during production
    function initialize(
        address _token,
        address _marketplaceSetting
    ) public initializer {
        isTokenSupport[_token] = true;
        marketplaceSetting = _marketplaceSetting;
    }

    // TODO uncommet during testing
    // constructor(address _marketplaceSetting,address _token) {
    //     marketplaceSetting = _marketplaceSetting;
    //     isTokenSupport[_token] = true;
    // }

    modifier isFreeze(){
        require(!IMarketplaceSetting(marketplaceSetting).isMarketplaceFreeze(),"SS_Marketplace: Marketplace is currently frozen");
        _;
    }

    function addCoin(address _token) external {
      require(msg.sender == IMarketplaceSetting(marketplaceSetting).s2Admin(), "SS_Marketplace: Unauthorized user");
      require(!isTokenSupport[_token],"SS_Marketplace: Token is currently supported");
      isTokenSupport[_token] = true;
    }

    function listVesting(
        address _vestingPlan,  
        uint256 _amount, 
        uint256 _price, 
        uint256 _discountPct, // Max is 100% cannot be less than 0.
        ListingType _listingType,  // 0 = Partial Fill, 1 = Single Fill 
        DiscountType _discountType, // 0 =  No Discount, 1 = Linear discount ,2 = Fix Discount 
        uint256 _maxWhitelist,
        address _currency,  // Input currency 
        uint256 _minPurchaseAmt,  // Input currency 
        bool _isPrivate // either true or false
    ) external isFreeze{
        require(_listingType != ListingType.SINGLE || (_minPurchaseAmt >0 && _minPurchaseAmt <=_amount),"SS_Marketplace: Minimum Purchase Amount cannot be more than listing amount");
        require(_price > 0, "SS_Marketplace: Price must be greater than 0");
        require((_discountType != DiscountType.NO  && _discountPct > 0) || (_discountType == DiscountType.NO), "SS_Marketplace: Invalid discount amount");
        require((_amount > 0 && (_listingType != ListingType.PARTIAL ||_listingType != ListingType.SINGLE )), "SS_Marketplace: Invalid listing amount");
        require(isTokenSupport[_currency],"SS_Marketplace: Payment token is not supported");
        IVestingManager(IMarketplaceSetting(marketplaceSetting).vestingManager()).listVesting(msg.sender, _vestingPlan, _amount);
        
        uint256 listingId = nextListingId[_vestingPlan]++;
        address whitelistAddress;

        if(_isPrivate){
            require(_maxWhitelist > 0, "SS_Marketplace: Minimum whitelist user cannot be 0");
            whitelistAddress = SecondSwap_WhitelistDeployer(IMarketplaceSetting(marketplaceSetting).whitelistDeployer()).deployWhitelist(_maxWhitelist,msg.sender);
            emit WhitelistCreated(_vestingPlan, listingId, whitelistAddress, msg.sender, _maxWhitelist);
        }

        listings[_vestingPlan][listingId] = Listing({
            seller: msg.sender,
            total: _amount,
            balance: _amount,
            pricePerUnit: _price,
            listingType: _listingType,
            discountType: _discountType,
            discountPct: _discountPct,
            listTime: block.timestamp,
            whitelist: whitelistAddress,
            currency: _currency,
            minPurchaseAmt: _minPurchaseAmt,
            status: Status.LIST
        });
        emit Listed(_vestingPlan, listingId);
    }

    function unlistVesting(
        address _vestingPlan, 
        uint256 _listingId 
    ) external isFreeze{
        Listing storage listing = listings[_vestingPlan][_listingId];
        require(listing.status == Status.LIST, "SS_Marketplace: Listing not active");
        require(listing.seller == msg.sender || msg.sender == IMarketplaceSetting(marketplaceSetting).s2Admin(), "SS_Marketplace: Not the seller");
        uint256 _penaltyFee = 0;
        if (msg.sender != IMarketplaceSetting(marketplaceSetting).s2Admin()){
            if ((listing.listTime + IMarketplaceSetting(marketplaceSetting).minListingDuration()) > block.timestamp) {
                require(IERC20(listing.currency).balanceOf(msg.sender) >= IMarketplaceSetting(marketplaceSetting).penaltyFee(), "SS_Marketplace: Penalty fee required for early unlisting");
                IERC20(listing.currency).transferFrom(msg.sender, IMarketplaceSetting(marketplaceSetting).feeCollector(), IMarketplaceSetting(marketplaceSetting).penaltyFee());
                _penaltyFee= IMarketplaceSetting(marketplaceSetting).penaltyFee();
            }
        }

        listing.status = Status.DELIST;
        IVestingManager(IMarketplaceSetting(marketplaceSetting).vestingManager()).unlistVesting(listing.seller, _vestingPlan, listing.balance);
        emit Delisted(_vestingPlan, _listingId, _penaltyFee, msg.sender);
    }

    // Buyer pay extra 2.5% as per the listed price
    // Seller get lesser 2.5% as per the listed price
       
    function _validatePurchase(
        Listing storage listing,
        uint256 _amount,
        address _referral
    ) private view {
        require(msg.sender != _referral, "SS_Marketplace: Invalid referral");
        require(listing.whitelist == address(0) || IWhitelist(listing.whitelist).validateAddress(msg.sender), "SS_Marketplace: Not whitelisted");
        require(listing.listingType == ListingType.SINGLE||(_amount >= listing.minPurchaseAmt || _amount == listing.balance),"SS_Marketplace: Invalid Purchase amount"); //Remove the checking if minPurhcaseAmt less than balance as they will need to buy the whole balance
        require(listing.listingType != ListingType.SINGLE || _amount == listing.total, "SS_Marketplace: Invalid amount");
        require(_amount <= listing.balance, "SS_Marketplace: Insufficient");
    }

    function _getDiscountedPrice(
        Listing storage listing,
        uint256 _amount
    ) private view returns (uint256) {
        uint256 discountedPrice = listing.pricePerUnit;
        
        if (listing.discountType == DiscountType.LINEAR) {
            discountedPrice = discountedPrice * 
                (BASE - (_amount * listing.discountPct / listing.total)) / BASE;
        } else if (listing.discountType == DiscountType.FIX) {
            discountedPrice = discountedPrice * 
                (BASE - listing.discountPct) / BASE;
        }
        return discountedPrice;
    }

    function _getFees(
        address _vestingPlan
    ) private view returns (uint256 bfee, uint256 sfee) {
        (int256 vpbf, int256 vpsf) = IMarketplaceSetting(marketplaceSetting).getVestingFees(_vestingPlan);
        bfee = vpbf > -1 ? uint256(vpbf) : IMarketplaceSetting(marketplaceSetting).buyerFee();
        sfee = vpsf > -1 ? uint256(vpsf) : IMarketplaceSetting(marketplaceSetting).sellerFee();
    }

    function _handleTransfers(
        Listing storage listing,
        uint256 _amount,
        uint256 discountedPrice,
        uint256 bfee,
        uint256 sfee,
        address _referral
    ) private returns (uint256 buyerFeeTotal, uint256 sellerFeeTotal, uint256 referralFeeCost) {
        // Calculate base amount
        uint256 baseAmount = (_amount * discountedPrice) / 1 ether;
        
        // Calculate fees
        buyerFeeTotal = (baseAmount * bfee) / BASE;
        sellerFeeTotal = (baseAmount * sfee) / BASE;  
        
        // Calculate total amount including buyer fee
        uint256 totalAmount = baseAmount + buyerFeeTotal;
        
        // Transfer from buyer to contract
        IERC20(listing.currency).transferFrom(msg.sender, address(this), totalAmount);
        
        // Handle referral if applicable
        referralFeeCost = 0;
        if (_referral != address(0) && listing.whitelist == address(0)) {
            referralFeeCost = buyerFeeTotal - (baseAmount * bfee * IMarketplaceSetting(marketplaceSetting).referralFee()) / (BASE * BASE);
            IERC20(listing.currency).transfer(_referral, referralFeeCost);
        }
        // Transfer to seller (base amount minus seller fee)
        uint256 sellerAmount = baseAmount - sellerFeeTotal;
        IERC20(listing.currency).transfer(listing.seller, sellerAmount);
        
        // Transfer to fee collector
        uint256 feeCollectorTotal = buyerFeeTotal - referralFeeCost + sellerFeeTotal;
        IERC20(listing.currency).transfer(IMarketplaceSetting(marketplaceSetting).feeCollector(),feeCollectorTotal);
    }

    function spotPurchase(
        address _vestingPlan,
        uint256 _listingId,
        uint256 _amount,
        address _referral
    ) external isFreeze {
        // Get listing and validate
        Listing storage listing = listings[_vestingPlan][_listingId];
        _validatePurchase(listing, _amount, _referral);

        // Get fees and price
        (uint256 bfee, uint256 sfee) = _getFees(_vestingPlan);
        uint256 discountedPrice = _getDiscountedPrice(listing, _amount);
        // Process transfers
        (uint256 buyerFeeTotal, uint256 sellerFeeTotal, uint256 referralFeeCost) = 
            _handleTransfers(listing, _amount, discountedPrice, bfee, sfee, _referral);

        // Update listing status
        listing.balance -= _amount;
        listing.status = listing.balance == 0 ? Status.SOLDOUT : Status.LIST;

        // Complete purchase
        IVestingManager(IMarketplaceSetting(marketplaceSetting).vestingManager())
            .completePurchase(msg.sender, _vestingPlan, _amount);

        // Emit event
        emit Purchased(
            _vestingPlan,
            _listingId,
            msg.sender,
            _amount,
            _referral,
            buyerFeeTotal,
            sellerFeeTotal,
            referralFeeCost
        );
    }

    
    function setMarketplaceSettingAddress(address _marketplaceSetting) external {
        require(msg.sender == IMarketplaceSetting(marketplaceSetting).s2Admin(), "SS_Marketplace: Unauthorized user");
        require(_marketplaceSetting != address(0),"SS_Marketplace: Address cannot be null");
        marketplaceSetting = _marketplaceSetting;
    }
    // TODO KIV POST[MVP] group purchase

    //TODO For testing of transparent proxy
    function version() public pure returns (string memory) {
        return "1.0.0";
    }

}

