// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./interface/SecondSwap_IMarketplaceSetting.sol";
import "./interface/SecondSwap_IVestingManager.sol";
import "hardhat/console.sol";

contract SecondSwap_MarketplaceSetting is IMarketplaceSetting {    

    uint256 public buyerFee;
    uint256 public sellerFee;
    uint256 public penaltyFee;
    uint256 public minListingDuration;
    uint256 public referralFee;
    bool public isMarketplaceFreeze;
    address public feeCollector;
    address public s2Admin;
    address public whitelistDeployer;
    address public vestingManager;
    address public referralFeeCollector;

    event DefaultBuyerFeeUpdated(uint256 buyerFee);
    event DefaultSellerFeeUpdated(uint256 sellerFee);
    event DefaultPenaltyFeeUpdated(uint256 penaltyFee);
    event PenaltyDurationUpdated(uint256 penaltyTime);
    event MarketplaceStatusUpdated(bool status);
    event FeeCollectorUpdated(address newCollector);
    event AdminUpdated(address newAdmin);
    event DevUpdated(address newDev);
    event ReferralUpdated(uint256 _percentage);

    constructor(
        address _feeCollector,
        address _s2Admin,
        address _whitelistDeployer,
        address _vestingManager

    ) {
        require(_feeCollector != address(0), "SS_Marketplace_Settings: Invalid fee collector address");
        require(_s2Admin != address(0), "SS_Marketplace_Settings: Invalid admin address");
        feeCollector = _feeCollector;
        s2Admin = _s2Admin;
        buyerFee = 250; // 2.5% fee
        sellerFee = 250; // 2.5% fee
        penaltyFee = 10 ether;
        minListingDuration = 120;
        referralFee = 1000;
        isMarketplaceFreeze = false;
        whitelistDeployer=_whitelistDeployer;
        vestingManager=_vestingManager;
    }

    modifier onlyAdmin() {
        require(msg.sender == s2Admin, "SS_Marketplace_Settings: Unauthorized user");
        _;
    }

    function setBuyerFee(uint256 _amount) external onlyAdmin {
        require(_amount <= 5000, "SS_Marketplace_Settings: Buyer fee cannot be more than 50%");
        buyerFee = _amount;
        emit DefaultBuyerFeeUpdated(_amount);
    }

    function setSellerFee(uint256 _amount) external onlyAdmin {
        require(_amount <= 5000, "SS_Marketplace_Settings: Seller fee cannot be more than 50%");
        sellerFee = _amount;
        emit DefaultSellerFeeUpdated(_amount);
    }
    
    function setFeeAccount(address _address) external onlyAdmin {
        require(_address != address(0), "SS_Marketplace_Settings: Cannot be zero address");
        require(_address != feeCollector, "SS_Marketplace_Settings: Cannot be the same address");
        feeCollector = _address;
        emit FeeCollectorUpdated(_address);
    }

    function setPenaltyFee(uint256 _amount) external onlyAdmin {
        require(_amount > 0, "SS_Marketplace_Settings: Penalty fee cannot be less than 0");
        penaltyFee = _amount;
        emit DefaultPenaltyFeeUpdated(_amount);
    }

    function setMinListingDuration(uint256 _seconds) external onlyAdmin {
        require(_seconds > 0, "SS_Marketplace_Settings: Duration must be greater than 0");
        minListingDuration = _seconds;
        emit PenaltyDurationUpdated(_seconds);
    }

    function setS2Admin(address _user) external {
        require(msg.sender == s2Admin,"SS_Marketplace_Settings: Unauthorized Access");
        require(_user != address(0), "SS_Marketplace_Settings: Cannot be zero address");
        require(_user != s2Admin, "SS_Marketplace_Settings: Cannot be the same address");
        s2Admin = _user;
        emit AdminUpdated(_user);
    }

    function setMarketplaceStatus(bool _status) external onlyAdmin {
        isMarketplaceFreeze = _status;
        emit MarketplaceStatusUpdated(_status);
    }
    
    function setReferral(uint256 _percentage) external onlyAdmin {
        require(_percentage > 0, "SS_Marketplace_Settings: Percentage value cannot be 0");
        require(_percentage <= 10000, "SS_Marketplace_Settings: Percentage cannot be more than 100%");
        referralFee = _percentage;
        emit ReferralUpdated(_percentage);
    }
    
    function setWhitelistDeployer(address _whitelistDeployer) external onlyAdmin {
        require(_whitelistDeployer != address(0), "SS_Marketplace_Settings: Cannot be zero address");
        require(_whitelistDeployer != address(whitelistDeployer), "SS_Marketplace_Settings: Cannot be the same whitelist address");
        whitelistDeployer = _whitelistDeployer;
    }
    
    function setManager(address _vestingManager) external onlyAdmin {
        require(_vestingManager != address(0), "SS_Marketplace_Settings: Cannot be zero address");
        require(_vestingManager != address(vestingManager), "SS_Marketplace_Settings: Cannot be the same vestingManager address");
        vestingManager = _vestingManager;
    }

    function getVestingFees(address _vesting) public view returns (int256 VPbuyerFee, int256 VPsellerFee) {
        (VPbuyerFee, VPsellerFee) = IVestingManager(vestingManager).getVestingFees(_vesting);
        return (VPbuyerFee, VPsellerFee);
    }

}

contracts/SecondSwap_StepVesting.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.24;

import "./interface/SecondSwap_Vesting.sol";

import "@openzeppelin/contracts/utils/math/Math.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "hardhat/console.sol";

contract SecondSwap_StepVesting is SecondSwap_Vesting {

	event VestingCreated(address indexed beneficiary, uint256 totalAmount);
	event VestingTransferred(address indexed grantor, address indexed beneficiary, uint256 amount);
	event Claimed(address indexed beneficiary, uint256 amount);

	IERC20 public immutable token;

	struct Vesting {
		uint256 stepsClaimed;
		uint256 amountClaimed;
		uint256 releaseRate;
		uint256 totalAmount;
	}

	uint256 immutable public startTime;
	uint256 immutable public endTime;
	uint256 immutable public numOfSteps;
	uint256 immutable public stepDuration;

	mapping (address => Vesting) public _vestings;
	address public vestingDeployer;
	address public manager;
	address public tokenIssuer;

	modifier onlyManager() {
		require(msg.sender == manager, "SS_StepVesting: caller is not the manager");
		_;
	}

	constructor(
		address _tokenIssuer,
		address _manager,
		IERC20 _token,
		uint256 _startTime,
		uint256 _endTime,
		uint256 _numOfSteps,
		address _vestingDeployer
	) {
		vestingDeployer = _vestingDeployer;
		tokenIssuer = _tokenIssuer;
		manager = _manager;
		token = _token;
		startTime = _startTime;
		endTime = _endTime;
		numOfSteps = _numOfSteps;
		stepDuration = (_endTime - _startTime) / _numOfSteps;
	}

	function available(address _beneficiary) external view returns (uint256) {
		return _vestings[_beneficiary].totalAmount - _vestings[_beneficiary].amountClaimed;
	}

	function total(address _beneficiary) external view returns (uint256) {
		return _vestings[_beneficiary].totalAmount;
	}

	function claimable(address _beneficiary) public view returns (uint256, uint256) {
		Vesting memory vesting = _vestings[_beneficiary];
		if (vesting.totalAmount == 0) {
			return (0, 0);
		}

		uint256 currentTime = Math.min(block.timestamp, endTime);
		if (currentTime < startTime) {
			return (0, 0);
		}

		uint256 elapsedTime = currentTime - startTime;
		uint256 currentStep = elapsedTime / stepDuration;
		uint256 claimableSteps = currentStep - vesting.stepsClaimed;
		
		uint256 claimableAmount;

		if (vesting.stepsClaimed + claimableSteps == numOfSteps) {
			claimableAmount = vesting.totalAmount - vesting.amountClaimed;
			return (claimableAmount, claimableSteps);
		}

		claimableAmount = vesting.releaseRate * claimableSteps;
		return (claimableAmount, claimableSteps);
	}

	function claim() external {
		(uint256 claimableAmount, uint256 claimableSteps) = claimable(msg.sender);
		require(claimableAmount > 0, "SS_StepVesting: nothing to claim");

		Vesting storage vesting = _vestings[msg.sender];
		vesting.stepsClaimed += claimableSteps;
		vesting.amountClaimed += claimableAmount;

		token.transfer(msg.sender, claimableAmount);
		emit Claimed(msg.sender, claimableAmount);
	}

	function transferVesting(
		address _grantor,
		address _beneficiary,
		uint256 _amount
	) external {
		require(msg.sender == tokenIssuer || msg.sender == manager || msg.sender == vestingDeployer, "SS_StepVesting: unauthorized");
		require(_beneficiary != address(0), "SS_StepVesting: beneficiary is zero");
		require(_amount > 0, "SS_StepVesting: amount is zero");
		Vesting storage grantorVesting = _vestings[_grantor];
		require(grantorVesting.totalAmount >= _amount, "SS_StepVesting: insufficient balance");

		
		grantorVesting.totalAmount -= _amount;
		grantorVesting.releaseRate = grantorVesting.totalAmount / numOfSteps;

		_createVesting(_beneficiary, _amount, grantorVesting.stepsClaimed, true);

		emit VestingTransferred(_grantor, _beneficiary, _amount);
	}

	function createVesting(
		address _beneficiary,
		uint256 _totalAmount
	) external {
		require(msg.sender == tokenIssuer || msg.sender == manager ||msg.sender == vestingDeployer, "SS_StepVesting: unauthorized");
		_createVesting(_beneficiary, _totalAmount, 0, false);
	}

	function createVestings(
		address[] memory _beneficiaries,
		uint256[] memory _totalAmounts
	) external {
		require(msg.sender == tokenIssuer || msg.sender == manager||msg.sender == vestingDeployer, "unauthorized");
		require(_beneficiaries.length == _totalAmounts.length, "SS_StepVesting: array length mismatch");

		for (uint256 i = 0; i < _beneficiaries.length; i++) {
			_createVesting(_beneficiaries[i], _totalAmounts[i], 0, false);
		}
	}

	function _createVesting(
		address _beneficiary,
		uint256 _totalAmount,
		uint256 _stepsClaimed,
		bool _isInternal
	) internal {
		require(_beneficiary != address(0), "SS_StepVesting: beneficiary is zero");
		require(_totalAmount > 0, "SS_StepVesting: total amount is zero");

		if (_vestings[_beneficiary].totalAmount == 0) {
			_vestings[_beneficiary] = Vesting({
				stepsClaimed: _stepsClaimed,
				amountClaimed: 0,
				releaseRate: _totalAmount / (numOfSteps - _stepsClaimed),
				totalAmount: _totalAmount
			});
		} else {
			_vestings[_beneficiary].totalAmount += _totalAmount;
			if(numOfSteps - _vestings[_beneficiary].stepsClaimed != 0){
				_vestings[_beneficiary].releaseRate = (_vestings[_beneficiary].totalAmount - _vestings[_beneficiary].amountClaimed) / (numOfSteps - _vestings[_beneficiary].stepsClaimed);
			}else{
				_vestings[_beneficiary].releaseRate = 0;
			}
		}
		
		if (!_isInternal) {
			token.transferFrom(tokenIssuer, address(this), _totalAmount);
		}
		emit VestingCreated(_beneficiary, _totalAmount);
	}

}

